#!/usr/bin/env python3
"""A SOP for a real entity (Organization) no longer shows "no deliverable contract" just because its text mentions another entity that has none.
Run from the repo root. Safe to run twice."""
import os, sys, json, zlib, base64
sys.stdout.reconfigure(errors='replace')
SYNC = json.loads('{"backend/app/services/sop_requirements.py": ""}')
ok = True

def rd(p):
    raw = open(p, 'rb').read().decode('utf-8'); return raw, ('\r\n' in raw), raw.replace('\r\n', '\n')
def wr(p, t, crlf): open(p, 'wb').write((t.replace('\n', '\r\n') if crlf else t).encode('utf-8'))

for path, b in SYNC.items():
    new = zlib.decompress(base64.b64decode(b))
    if os.path.exists(path):
        old, crlf, t = rd(path)
        if t.encode('utf-8') == new: print("same      ", path); continue
        bk = os.path.join(os.path.expanduser("~/xtrium_backup_58"), path)
        os.makedirs(os.path.dirname(bk), exist_ok=True); open(bk, 'wb').write(old.encode('utf-8'))
        verb = "replaced  "
    else:
        crlf = False; verb = "created   "; os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    wr(path, new.decode('utf-8'), crlf); print(verb, path)

print()
print("All applied." if ok else "Some edits did not match: paste the lines above and I will fit them to your files.")
